  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket with a title, description, and optional priority.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short summary of the issue.' },
          description: { type: 'string', description: 'Detailed description of the issue.' },
          priority: {
            type: 'string',
            enum: PRIORITIES,
            default: 'normal',
            description: 'Ticket priority.'
          }
        },
        required: ['title', 'description'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null) {
    throw new Error('Invalid arguments: expected an object');
  }

  const { title, description, priority } = args;

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Invalid arguments: title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.trim() === '') {
    throw new Error('Invalid arguments: description must be a non-empty string');
  }

  const resolvedPriority =
    priority === undefined ? 'normal' : priority;
  if (!PRIORITIES.includes(resolvedPriority)) {
    throw new Error(
      `Invalid arguments: priority must be one of ${PRIORITIES.join(', ')}`
    );
  }

  nextId += 1;
  const id = `t${nextId}`;

  return {
    content: [
      {
        type: 'text',
        text: `Created ticket ${id}: "${title}" (priority: ${resolvedPriority}).`
      }
    ]
  };
}

